import csv, re
from datetime import datetime
from collections import Counter, defaultdict

rows=list(csv.DictReader(open('expenses.csv')))

def parse_date(s):
    s=s.strip()
    for fmt in ('%m/%d/%Y','%d %b %Y','%Y-%m-%d'):
        try: return datetime.strptime(s,fmt).date()
        except ValueError: pass
    raise ValueError(s)

def parse_amount(s):
    s=s.strip().replace('USD','').replace('$','').replace(',','').strip()
    return round(float(s),2)

def norm_cat(s):
    s=s.strip().lower()
    return {'saas':'SaaS','airbnb':'Airbnb'}.get(s, s.title())

seen=set(); uniq=[]
for r in rows:
    rid=r['id'].strip()
    if rid in seen: continue
    seen.add(rid)
    uniq.append(r)

print('unique',len(uniq))
by_month=defaultdict(list)
for r in uniq:
    d=parse_date(r['date'])
    by_month[(d.year,d.month)].append((r,d))
for k,v in sorted(by_month.items()):
    print(k,len(v),sum(parse_amount(r['amount']) for r,d in v))
print()
oct_ok=[(r,d) for r,d in by_month[(2026,10)] if r['status'].strip().lower()=='ok']
oct_void=[(r,d) for r,d in by_month[(2026,10)] if r['status'].strip().lower()!='ok']
print('oct ok',len(oct_ok),round(sum(parse_amount(r['amount']) for r,d in oct_ok),2))
print('oct void',len(oct_void),[(r['id'],r['date'],r['category'],r['amount']) for r,d in oct_void])
cats=defaultdict(list)
for r,d in oct_ok:
    cats[norm_cat(r['category'])].append((r,d))
for cat,items in sorted(cats.items()):
    print(cat,len(items),round(sum(parse_amount(r['amount']) for r,d in items),2))
print('cats total',round(sum(sum(parse_amount(r['amount']) for r,d in v) for v in cats.values()),2))
EOF", "description": "Parse dates, dedupe, summarize October"}

